// ====================================================================
// SPECIFIED FACEBOOK PAGES TO MONITOR FOR INACTIVITY
// Target: Notify at 10 AM Karachi if no post published in last 2 days
// ====================================================================
const targetType = $input.item.json?.targetType || 'group';
const targetDestination = $input.item.json?.targetDestination || $input.item.json?.groupName || 'Marketing Team Alerts';
const targetGroupId = $input.item.json?.groupJid || $input.item.json?.groupId || '120363024829103948@g.us';

// All requested 8 Facebook Pages:
const pages = [
  {
    pageName: 'The Repair Pros',
    url: 'https://www.facebook.com/therepairpros/',
    pageHandle: 'therepairpros',
    pageId: 'therepairpros',
    accessToken: '',
    simulatedLastPostIso: ''
  },
  {
    pageName: 'The Bakery Cafe PK',
    url: 'https://www.facebook.com/thebakerycafepk',
    pageHandle: 'thebakerycafepk',
    pageId: 'thebakerycafepk',
    accessToken: '',
    simulatedLastPostIso: ''
  },
  {
    pageName: 'Alif School & College',
    url: 'https://www.facebook.com/alifschoolandcollege',
    pageHandle: 'alifschoolandcollege',
    pageId: 'alifschoolandcollege',
    accessToken: '',
    simulatedLastPostIso: ''
  },
  {
    pageName: 'Alif Degree College',
    url: 'https://www.facebook.com/alifdegreecollege',
    pageHandle: 'alifdegreecollege',
    pageId: 'alifdegreecollege',
    accessToken: '',
    simulatedLastPostIso: ''
  },
  {
    pageName: 'ISLE PK',
    url: 'https://www.facebook.com/islepk',
    pageHandle: 'islepk',
    pageId: 'islepk',
    accessToken: '',
    simulatedLastPostIso: ''
  },
  {
    pageName: 'Blossoms Pre-School',
    url: 'https://www.facebook.com/Blossomspreschool',
    pageHandle: 'Blossomspreschool',
    pageId: 'Blossomspreschool',
    accessToken: '',
    simulatedLastPostIso: ''
  },
  {
    pageName: 'The British School Mardan',
    url: 'https://www.facebook.com/TheBritishSchoolMardan',
    pageHandle: 'TheBritishSchoolMardan',
    pageId: 'TheBritishSchoolMardan',
    accessToken: '',
    simulatedLastPostIso: ''
  },
  {
    pageName: 'Basma Emaar Group',
    url: 'https://www.facebook.com/basmaemaargroup',
    pageHandle: 'basmaemaargroup',
    pageId: 'basmaemaargroup',
    accessToken: '',
    simulatedLastPostIso: ''
  }
];

return pages.map(page => ({
  json: {
    ...page,
    targetType,
    targetDestination,
    targetGroupId,
    checkedAt: new Date().toISOString()
  }
}));

// Calculate 2-day inactivity relative to Asia/Karachi calendar days
const item = $input.item.json;
const pageInfo = $('List of Monitored Facebook Pages').item.json;
const pageName = pageInfo.pageName;
const targetType = pageInfo.targetType || 'group';
const targetDestination = pageInfo.targetDestination || 'Marketing Team Alerts';
const targetGroupId = pageInfo.targetGroupId || '120363024829103948@g.us';

// 1. Determine last published post timestamp
let lastPostTime = 0;
if (item.data && Array.isArray(item.data) && item.data.length > 0 && item.data[0].created_time) {
  lastPostTime = new Date(item.data[0].created_time).getTime();
} else if (pageInfo.simulatedLastPostIso) {
  lastPostTime = new Date(pageInfo.simulatedLastPostIso).getTime();
} else {
  // If no API token provided yet or empty feed, default to inactive (3 days ago)
  lastPostTime = Date.now() - (72 * 60 * 60 * 1000);
}

// 2. Compute Karachi 2-day calendar threshold
// "By 2 days I mean, like if nothing has been posted on date 16, and 17. It should message on date 18, 10am. Karachi time."
const tz = 'Asia/Karachi';
const now = new Date();
const karachiDateStr = now.toLocaleDateString('en-CA', { timeZone: tz }); // YYYY-MM-DD
const [todayY, todayM, todayD] = karachiDateStr.split('-').map(Number);

// Today 00:00:00 PKT in UTC milliseconds (PKT = UTC+5)
const todayStartUtc = Date.UTC(todayY, todayM - 1, todayD, -5, 0, 0);
const twoDaysAgoStartUtc = todayStartUtc - (48 * 60 * 60 * 1000); // 2 full calendar days prior

// Active if a post was published during Day -2, Day -1, or Today
const hasPostedInLast2Days = lastPostTime >= twoDaysAgoStartUtc;
const isInactive = !hasPostedInLast2Days;

// Requested exact message format:
// <Page name> is inactive since 48 hours.
const alertMessage = `${pageName} is inactive since 48 hours.`;

return [{
  json: {
    pageName,
    url: pageInfo.url,
    pageHandle: pageInfo.pageHandle,
    lastPostTime: new Date(lastPostTime).toISOString(),
    isInactive,
    alertMessage,
    targetType,
    targetDestination,
    targetGroupId,
    checkedDateKarachi: karachiDateStr
  }
}];

const item = $input.item.json;
return [{
  json: {
    success: true,
    status: 'ALERT_TRIGGERED',
    pageName: item.pageName,
    pageUrl: item.url,
    message: item.alertMessage,
    targetType: item.targetType,
    targetDestination: item.targetDestination,
    groupName: item.targetDestination,
    groupJid: item.targetGroupId,
    timestamp: new Date().toISOString()
  }
}];
